//! A real Root process serves only the already registered daemon's fixed Cell
//! and Source lanes. Config, AgentdState, SQL writer and private receipts stay
//! in that daemon. No thread is used as a replacement for process credentials.

use std::os::unix::net::UnixStream;
use std::sync::Arc;
use std::time::Duration;
use std::time::Instant;

use codex_hepta_contracts::HostAuthorityPeerChannel;
use codex_hepta_contracts::HostAuthorityPeerPolicy;
use codex_hepta_contracts::HostIssuerPeer;
use codex_hepta_neuron::AnchorWitnessStore;

use super::PreparedRootHostCircuitTaskV1;
use crate::{AgentdError, CircuitTaskSourceReadbackV1, OriginalRootCircuitTaskCustodyV1};
use crate::circuit_task::remote::OriginalRootTaskStreams;

impl<SW, CW> PreparedRootHostCircuitTaskV1<SW, CW>
where SW: AnchorWitnessStore + Send + 'static, CW: AnchorWitnessStore + Send + 'static,
{
    /// Consume this runtime's one actual factory lane. Both streams must have
    /// been connected by the registered non-Root process; their two pidfds are
    /// duplicates of this session's same pre-held process handle. The nonce
    /// separates the fixed lanes and grants no task, model or effect authority.
    ///
    /// This synchronous scope owns the actual work until it returns. A caller
    /// cancelling its await cannot release these owners. Any error is Unknown;
    /// this value retains only its original readback/drain custody, never a new
    /// lane, a new operation or an automatic Create/Execute retry.
    pub fn serve_original_root_circuit_task(&mut self, task: UnixStream, loan: UnixStream,
        session_nonce: [u8; 16]) -> Result<u64, AgentdError>
    {
        self.read_original_root_task_generation()?;
        let identity = self.session.registration.registered_identity.identity()?;
        if self.session.config.peer_uid == 0 || self.session.registration.peer_pid == std::process::id()
            || session_nonce == [0; 16]
        { return Err(AgentdError::Invalid("original Root task peer or session differs".into())); }
        let lifetime = self.end.checked_duration_since(Instant::now())
            .filter(|value| !value.is_zero() && *value <= Duration::from_secs(300))
            .ok_or_else(|| AgentdError::Invalid("original Root task scope expired".into()))?;
        let policy = HostAuthorityPeerPolicy {
            peer: HostIssuerPeer { uid: self.session.config.peer_uid, pid: self.session.registration.peer_pid },
            timeout: Duration::from_millis(self.session.config.timeout_ms.min(500)), lifetime,
            request_bound: 65_536, response_bound: 65_536,
        };
        let task = HostAuthorityPeerChannel::from_stream(task, policy, self.session.owner_pidfd.try_clone()?)
            .map_err(|error| AgentdError::Protocol(error.to_string()))?;
        let loan = HostAuthorityPeerChannel::from_stream(loan, policy, self.session.owner_pidfd.try_clone()?)
            .map_err(|error| AgentdError::Protocol(error.to_string()))?;
        let lane = self.runtime.take_original_root_lane()?;
        crate::circuit_task::remote::serve(self, &identity, lane,
            OriginalRootTaskStreams::new(task, loan, session_nonce, self.end))
            .map_err(|error| AgentdError::Protocol(format!("original Root task service: {error}")))
    }

    pub(crate) fn require_original_root_task_source(&self,
        source: &Arc<CircuitTaskSourceReadbackV1<SW>>) -> Result<(), AgentdError>
    {
        self.read_original_root_task_generation()?;
        OriginalRootCircuitTaskCustodyV1::require_original_source(&self.custody, source)
    }
}

//! Shared Agentd composition: a durable Circuit admission enters the native
//! Cell pipeline, then returns a completion only after the Cell owner commits.
//! This computation facility never invokes tools or publishes external effects.

#[path = "circuit_cell_batch.rs"]
mod batch;
#[cfg(target_os = "linux")]
#[path = "circuit_cell_remote.rs"]
mod original_remote;

use std::cell::Cell;
use std::error::Error;
use std::fmt;

use codex_hepta_automation::CircuitCompletionV2;
use codex_hepta_automation::CircuitComputationAdmissionV2;
use codex_hepta_contracts::Sha256Digest;
use codex_hepta_neuron::CellCandidateKindV1;
use codex_hepta_neuron::CellDecisionReceiptV1;
use codex_hepta_neuron::CellExecutionError;
use codex_hepta_neuron::CellInferenceReadbackPortV1;
use codex_hepta_neuron::CellInputEncoderV1;
use codex_hepta_neuron::CellStateOwnerV1;
use codex_hepta_neuron::CellStepEntryV1;
use codex_hepta_neuron::CellStepInputV1;
use codex_hepta_neuron::NeuronInferenceControlPort;
use codex_hepta_neuron::canonical_cell_step_request_digest_v1;
use codex_hepta_neuron::commit_cell_step;
use codex_hepta_neuron::decide_cell;
use codex_hepta_neuron::enter_cell_step;
use codex_hepta_neuron::infer_cell_with_clock;
use codex_hepta_neuron::recover_cell_inference;
use codex_hepta_types::AuthorityPosture;

use crate::CircuitCellBindingV1;
use crate::CircuitCellRegistryV1;
use crate::circuit_cell_dispatch::GuardedCellDispatchV1;
use crate::circuit_cell_output::encode_output;
use crate::circuit_cell_output::encode_receipt;
use crate::circuit_cell_ports::circuit_cell_output_schema_v2;
use crate::circuit_cell_ports::encode_ports;

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum CircuitCellErrorV1 {
    InvalidBinding,
    ScopeMismatch,
    InputMismatch,
    InvalidReceipt,
    ReconciliationRequired,
    Cell(CellExecutionError),
}

impl fmt::Display for CircuitCellErrorV1 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "{self:?}")
    }
}
impl Error for CircuitCellErrorV1 {}
impl From<CellExecutionError> for CircuitCellErrorV1 {
    fn from(error: CellExecutionError) -> Self {
        Self::Cell(error)
    }
}

/// The two owners use explicit time units. Their clock epochs need not match.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CircuitCellTimeV1 {
    pub circuit_millis: u64,
    pub cell_micros: u64,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CircuitCellExecutionV1 {
    pub completion: CircuitCompletionV2,
    pub decision: CellDecisionReceiptV1,
    /// Exact canonical bytes named by completion.output_digest.
    pub output: Vec<u8>,
}

/// One long-lived owner for many cells. O owns partitioned state, P owns the
/// shared inference facility, and E resolves frozen encoders. Construction
/// does not activate this facility in the daemon's ordinary startup path.
pub struct AgentdCircuitCellOwnerV1<O, P, E> {
    registry: CircuitCellRegistryV1,
    state_owner: O,
    inference_control: P,
    encoder: E,
}

impl<O, P, E> AgentdCircuitCellOwnerV1<O, P, E>
where
    O: CellStateOwnerV1,
    P: NeuronInferenceControlPort + CellInferenceReadbackPortV1,
    E: CellInputEncoderV1,
{
    pub fn new(
        registry: CircuitCellRegistryV1,
        state_owner: O,
        inference_control: P,
        encoder: E,
    ) -> Self {
        Self {
            registry,
            state_owner,
            inference_control,
            encoder,
        }
    }

    pub fn registry(&self) -> &CircuitCellRegistryV1 {
        &self.registry
    }
    pub fn state_owner(&self) -> &O {
        &self.state_owner
    }
    pub fn state_owner_mut(&mut self) -> &mut O {
        &mut self.state_owner
    }

    /// Consume an owner-issued admission. Raw dispatch DTOs cannot call this
    /// entry point. On any error the Circuit keeps its reservation; neither a
    /// missing response nor an absent Cell receipt proves no computation.
    ///
    /// The caller commits the returned completion with its existing Circuit
    /// fence/CAS. Losing that acknowledgement is recovered from the same Cell
    /// operation and never repeats encoding, inference or state advancement.
    pub fn execute(
        &mut self,
        admission: CircuitComputationAdmissionV2,
        input: CellStepInputV1,
        mut clock: impl FnMut() -> CircuitCellTimeV1,
    ) -> Result<CircuitCellExecutionV1, CircuitCellErrorV1> {
        let dispatch = admission.dispatch();
        let binding = self.registry.bind_input(dispatch, &input)?;
        let request_digest = canonical_cell_step_request_digest_v1(&binding.cell, &input)?;
        if admission.owner_agent_id().as_str() != input.scope.agent_id.as_str()
            || admission.definition_digest() != self.registry.definition_digest()
            || admission
                .execution_request_digest()
                .is_none_or(|digest| digest.as_str() != request_digest.to_string())
        {
            return Err(CircuitCellErrorV1::ScopeMismatch);
        }
        let time = clock();
        if time.circuit_millis < admission.observed_at_ms() {
            return Err(CircuitCellErrorV1::ReconciliationRequired);
        }
        let admission_deadline = admission
            .lease_expires_at_ms()
            .min(admission.run_deadline_ms());
        let read_only =
            admission.reconciliation_only() || time.circuit_millis >= admission_deadline;
        let committed =
            match self
                .state_owner
                .lookup(&input.scope, &input.operation_id, request_digest)
            {
                Ok(receipt) => receipt,
                Err(CellExecutionError::InferencePending) => None,
                Err(error) => return Err(error.into()),
            };
        let mut last_time = time;
        let decision = if let Some(receipt) = committed {
            receipt
        } else {
            let pending = self.state_owner.pending_inference(&input.scope)?;
            let inferred = if pending.is_some() {
                recover_cell_inference(
                    &binding.cell,
                    &self.state_owner,
                    &self.encoder,
                    input.clone(),
                    &mut self.inference_control,
                    time.cell_micros,
                )?
            } else {
                if read_only {
                    return Err(CircuitCellErrorV1::ReconciliationRequired);
                }
                match enter_cell_step(
                    &binding.cell,
                    &self.state_owner,
                    &self.encoder,
                    input.clone(),
                    time.cell_micros,
                )? {
                    CellStepEntryV1::Ready(prepared) => {
                        let sampled = Cell::new(time);
                        // The inference entry samples immediately after durable
                        // admission. Use that same live sample for the Circuit
                        // guard so its queue measurement ends at this boundary.
                        let mut dispatch_clock = || sampled.get();
                        let mut guarded = GuardedCellDispatchV1::new(
                            &mut self.inference_control,
                            &mut dispatch_clock,
                            time,
                            admission_deadline,
                            input.deadline_micros,
                        );
                        let mut invalid_clock = false;
                        let inferred = infer_cell_with_clock(
                            *prepared,
                            &mut self.state_owner,
                            &mut guarded,
                            || {
                                let before = sampled.get();
                                let now = clock();
                                if now.circuit_millis < before.circuit_millis
                                    || now.cell_micros < before.cell_micros
                                    || now.circuit_millis >= admission_deadline
                                {
                                    invalid_clock = true;
                                    return u64::MAX;
                                }
                                sampled.set(now);
                                now.cell_micros
                            },
                        );
                        if invalid_clock {
                            return Err(CircuitCellErrorV1::ReconciliationRequired);
                        }
                        let inferred = inferred?;
                        last_time = guarded
                            .observed_at()
                            .ok_or(CircuitCellErrorV1::ReconciliationRequired)?;
                        inferred
                    }
                    CellStepEntryV1::Replayed(receipt) => {
                        return finish(binding, dispatch, &input, *receipt);
                    }
                }
            };
            let decided_at = clock();
            if decided_at.circuit_millis < last_time.circuit_millis
                || decided_at.cell_micros < last_time.cell_micros
            {
                return Err(CircuitCellErrorV1::ReconciliationRequired);
            }
            let proposal = decide_cell(inferred, decided_at.cell_micros)?;
            let committed_at = clock();
            if committed_at.circuit_millis < decided_at.circuit_millis
                || committed_at.cell_micros < decided_at.cell_micros
            {
                return Err(CircuitCellErrorV1::ReconciliationRequired);
            }
            commit_cell_step(&mut self.state_owner, proposal, committed_at.cell_micros)?
        };
        finish(binding, dispatch, &input, decision)
    }
}

pub(crate) fn finish(
    binding: &CircuitCellBindingV1,
    dispatch: &codex_hepta_automation::CircuitDispatchV2,
    input: &CellStepInputV1,
    decision: CellDecisionReceiptV1,
) -> Result<CircuitCellExecutionV1, CircuitCellErrorV1> {
    let selected = binding
        .cell
        .candidates
        .iter()
        .position(|candidate| candidate.candidate_id == decision.selected_candidate)
        .ok_or(CircuitCellErrorV1::InvalidReceipt)?;
    if decision.operation_id != input.operation_id
        || decision.scope != input.scope
        || decision.bundle_digest != binding.cell.bundle_digest
        || decision.source_frontier != input.source_frontier
        || decision.semantic_request_digest
            != canonical_cell_step_request_digest_v1(&binding.cell, input)?
        || decision.authority != AuthorityPosture::DENY_ALL
        || decision.operation_digest.is_zero()
        || decision.model_output_digest.is_zero()
        || decision.checkpoint_after.is_zero()
        || decision.confidence_ppm > 1_000_000
        || decision.ood_ppm > 1_000_000
        || decision
            .cost
            .consumed_input_bytes
            .checked_add(decision.cost.truncated_input_bytes)
            != Some(input.observation.len())
        || decision.policy.len() != binding.cell.candidates.len()
        || input.candidates.len() != decision.policy.len()
        || (decision.deadline_exceeded
            && binding.cell.candidates[selected].kind != CellCandidateKindV1::Abstain)
    {
        return Err(CircuitCellErrorV1::InvalidReceipt);
    }
    for (index, ((policy, mask), candidate)) in decision
        .policy
        .iter()
        .zip(&input.candidates)
        .zip(&binding.cell.candidates)
        .enumerate()
    {
        if policy.candidate_id != candidate.candidate_id
            || mask.candidate_id != candidate.candidate_id
            || policy.allowed != mask.allowed
            || policy.probability_ppm != if index == selected { 1_000_000 } else { 0 }
            || (index == selected && !policy.allowed)
        {
            return Err(CircuitCellErrorV1::InvalidReceipt);
        }
    }
    let route = &binding.routes[selected];
    let output = if dispatch.output_schema == circuit_cell_output_schema_v2() {
        if decision.representation.drive_q24.len() != binding.cell.runtime.state_width {
            return Err(CircuitCellErrorV1::InvalidReceipt);
        }
        encode_ports(&decision, binding.cell.state_schema_digest)?
    } else {
        encode_output(&decision)?
    };
    let output_digest = Sha256Digest::for_bytes(&output);
    let mut receipt_bytes = b"hepta.circuit.cell-completion.v1\0".to_vec();
    receipt_bytes.extend_from_slice(dispatch.invocation_digest.as_str().as_bytes());
    receipt_bytes.extend_from_slice(output_digest.as_str().as_bytes());
    receipt_bytes.extend_from_slice(&encode_receipt(&decision)?);
    let completion = CircuitCompletionV2 {
        activation_id: dispatch.activation_id,
        invocation_digest: dispatch.invocation_digest.clone(),
        output_digest,
        receipt_digest: Sha256Digest::for_bytes(&receipt_bytes),
        // Preserve actual work, including an overrun. The Circuit owner records
        // the full charge and takes WorkBudget fallback instead of clamping it.
        actual_work: decision.cost.model_latency_micros,
        outcome: route.outcome,
        selected_edges: route.selected_edges.clone(),
