            profile.files.source_journal,
            profile.files.source_witness,
            identity,
            &profile.fence,
            &registry,
            vec![source_input],
        ),
        CircuitQ24TaskOpenModeV1::Recover => DurableCircuitTaskSourceV1::recover(
            profile.files.source_journal,
            profile.files.source_witness,
            identity,
            &profile.fence,
            &registry,
            vec![source_input],
        ),
    }
    .map_err(|error| AgentdError::Invalid(error.to_string()))?;
